-- DASH-247 baseline dashboard — initial schema.
--
-- Adapted from the portable schema.sql at the repository root:
--   * TIMESTAMP (UTC, naive) -> timestamptz. The seed data is UTC; storing an
--     instant with an explicit zone is what makes per-account day bucketing safe
--     (`occurred_at AT TIME ZONE accounts.timezone`).
--   * SERIAL/IDENTITY: ids are GENERATED BY DEFAULT so the seed can keep its own
--     ids; the loader resets the sequences afterwards.
--   * Deliberately no unique constraint on the event identity: two genuinely
--     simultaneous identical events are legal in the source system. The known
--     duplicate rows in seed.sql are dropped once by the loader, which reports
--     exactly how many it dropped.
--   * event_type is constrained because the dashboard can only speak about these
--     three kinds of activity: an unknown type would silently vanish from every
--     metric, which is worse than failing the write.

CREATE TABLE accounts (
    id          integer      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        varchar(120) NOT NULL,
    industry    varchar(60)  NOT NULL,
    timezone    varchar(60)  NOT NULL, -- IANA zone, e.g. 'America/Chicago'
    created_at  timestamptz  NOT NULL
);

CREATE TABLE activity_events (
    id                integer      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id        integer      NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    location          varchar(80)  NOT NULL,
    event_type        varchar(40)  NOT NULL
        CHECK (event_type IN ('call_received', 'lead_created', 'appointment_set')),
    occurred_at       timestamptz  NOT NULL,
    duration_seconds  integer      NULL
        CHECK (duration_seconds IS NULL OR duration_seconds >= 0),
    outcome           varchar(40)  NULL,
    loaded_at         timestamptz  NOT NULL DEFAULT now()
);

-- Every read is "this account, this date range" and, for the location breakdown,
-- "...grouped by location".
CREATE INDEX activity_events_account_occurred_idx
    ON activity_events (account_id, occurred_at);

CREATE INDEX activity_events_account_location_occurred_idx
    ON activity_events (account_id, location, occurred_at);
